import { buildHeatmapLayout, heatColor, CELL_SPACING } from "@/lib/scene/heatmap";
import type { ChartSpec } from "@/lib/types";

/**
 * Oracle: every expected number below is hand-computed from the fixture by a
 * human, not generated by the implementation under test. Same discipline as
 * the stats and DAX suites.
 */

const SPEC: ChartSpec = {
  kind: "heatmap",
  title: "Revenue heat by segment",
  categories: ["Q1", "Q2", "Q3", "Q4"],
  rowLabels: ["Enterprise", "SMB"],
  series: [
    { name: "Enterprise", data: [10, 20, 30, 40] },
    { name: "SMB", data: [5, 15, 25, 50] },
  ],
};

describe("heatmap layout — hand-computed oracle", () => {
  const layout = buildHeatmapLayout(SPEC);

  it("encodes exactly the quantitative values in the spec (8 cells)", () => {
    expect(layout.cellCount).toBe(8);
    expect(layout.cells).toHaveLength(8);
  });

  it("normalizes intensity against global min 5 and max 50", () => {
    expect(layout.minValue).toBe(5);
    expect(layout.maxValue).toBe(50);
    // t = (v - 5) / (50 - 5), hand-computed:
    expect(layout.cells.find((c) => c.value === 5)?.t).toBeCloseTo(0);
    expect(layout.cells.find((c) => c.value === 50)?.t).toBeCloseTo(1);
    expect(layout.cells.find((c) => c.value === 10)?.t).toBeCloseTo((10 - 5) / 45);
    expect(layout.cells.find((c) => c.value === 30)?.t).toBeCloseTo(25 / 45);
  });

  it("keeps the raw value on every cell — the 3D mirrors, never invents", () => {
    for (const cell of layout.cells) {
      const row = SPEC.series[cell.row];
      expect(cell.value).toBe(row?.data?.[cell.col]);
    }
  });

  it("places cells on a deterministic grid centred at origin", () => {
    // 4 columns → x offsets (-1.5, -0.5, 0.5, 1.5) * spacing; 2 rows → z ±0.5.
    const q1 = layout.cells.find((c) => c.col === 0)!;
    expect(q1.x).toBeCloseTo(-1.5 * CELL_SPACING);
    const q4 = layout.cells.find((c) => c.col === 3)!;
    expect(q4.x).toBeCloseTo(1.5 * CELL_SPACING);
    const row0 = layout.cells.find((c) => c.row === 0)!;
    expect(row0.z).toBeCloseTo(-0.5 * CELL_SPACING);
    const row1 = layout.cells.find((c) => c.row === 1)!;
    expect(row1.z).toBeCloseTo(0.5 * CELL_SPACING);
  });

  it("computes per-column maxima the peak markers can trust", () => {
    expect(layout.colMaxima).toEqual([10, 20, 30, 50]);
  });

  it("leaves gaps as gaps: non-finite values produce no invented cell", () => {
    const gappy: ChartSpec = {
      kind: "heatmap",
      title: "gaps",
      categories: ["a", "b", "c"],
      series: [{ name: "s", data: [1, null as unknown as number, 3] }],
    };
    const l = buildHeatmapLayout(gappy);
    expect(l.cellCount).toBe(2);
    expect(l.cells.map((c) => c.col).sort()).toEqual([0, 2]);
  });

  it("is deterministic — same spec, same layout, twice", () => {
    expect(buildHeatmapLayout(SPEC)).toEqual(buildHeatmapLayout(SPEC));
  });

  it("degrades safely on an empty spec", () => {
    const l = buildHeatmapLayout({ kind: "heatmap", title: "empty", series: [] });
    expect(l.cellCount).toBe(0);
    expect(l.cells).toEqual([]);
  });
});

describe("heat color ramp — endpoints and clamping", () => {
  it("cold at t=0, hot amber at t=1", () => {
    expect(heatColor(0)).toBe("#143a4a");
    expect(heatColor(1)).toBe("#ffb400");
  });

  it("clamps out-of-range input instead of producing garbage", () => {
    expect(heatColor(-2)).toBe("#143a4a");
    expect(heatColor(7)).toBe("#ffb400");
  });

  it("midpoint is between the endpoints on every channel", () => {
    const mid = heatColor(0.5);
    // Hand-computed per channel: r (20+255)/2→138=0x8a, g (58+180)/2→119=0x77, b (74+0)/2→37=0x25.
    expect(mid).toBe("#8a7725");
  });
});
